const dictionaries: Record<Language, Dict> = { en, fi, fa, ar, ru, zh, ko, ja, de, es, fr };

export const translations = Object.fromEntries(
  Object.entries(dictionaries).map(([language, dictionary]) => [language, { ...en, ...dictionary, ...uiLocalized[language as Language], ...capacityLocalized[language as Language], ...locationLocalized[language as Language] }]),
) as Record<Language, typeof en>;
